hooks.command:
node -e "
const fs = require('fs');
const path = process.env.TOOL_INPUT_FILE_PATH || '';
if (!path) process.exit(0);
try {
  const lines = fs.readFileSync(path, 'utf8').split('\n').length;
  if (lines > 300) {
    console.error('[quality] WARNING: ' + path + ' has ' + lines + ' lines (limit: 300). Consider splitting.');
  }
} catch(e) { process.exit(0); }
"

node -e "
const cmd = process.env.TOOL_INPUT_COMMAND || '';
if (/\b(npm|bun|yarn)\s+(add|install|i|remove|uninstall)\b/.test(cmd) && !/npm install -g/.test(cmd)) {
  console.error('[quality] Use `pnpm add` instead - this project uses pnpm for package management.');
  process.exit(2);
}
"

node -e "
const path = process.env.TOOL_INPUT_FILE_PATH || '';
if (!path) process.exit(0);
if (/\.(js|jsx)$/.test(path) && !/\.config\.(js|mjs|cjs)$/.test(path)) {
  console.error('[ts] ' + path + ' is plain JavaScript. Write TypeScript (.ts/.tsx) - JS only for configs that cannot load TS.');
}
"

node -e "
const fs = require('fs');
const path = process.env.TOOL_INPUT_FILE_PATH || '';
if (!path) process.exit(0);
try {
  const src = fs.readFileSync(path, 'utf8');
  if (/console\.log/.test(src)) {
    console.error('[quality] Remove console.log before committing: ' + path);
  }
} catch(e) { process.exit(0); }
"

node -e "
const cmd = process.env.TOOL_INPUT_COMMAND || '';
const m = cmd.match(/git\s+(?:checkout\s+-b|switch\s+-c)\s+(\S+)/);
if (m && !/^-/.test(m[1]) && !/\b[A-Z][A-Z0-9]*-[0-9]+\b/.test(m[1])) {
  console.error('[git] Branch ' + m[1] + ' has no ticket ID. Ticketed work uses type/TICKET-123-short-description (see git-workflow.md).');
}
"

node -e "
const cmd = process.env.TOOL_INPUT_COMMAND || '';
if (/git\s+commit/.test(cmd) && !/--amend/.test(cmd)) {
  console.error('[git] Reminder: run linter + type checker + tests before committing (see git-workflow.md). Proceed only if checks passed.');
}
"

node -e "
const cmd = process.env.TOOL_INPUT_COMMAND || '';
if (/git\s+push/.test(cmd) && /\b(main|master)\b/.test(cmd)) {
  console.error('[git] Pushing directly to main/master is not allowed. Use a feature branch and open a PR.');
  process.exit(2);
}
"

node -e "
